  fun getRegions(): List<String> = listOf(
    "All 195",
    "Popular",
    "Europe",
    "Americas",
    "Asia & Pacific",
    "Middle East",
    "Africa"
  )

  fun filter(query: String, region: String): List<VpnServer> {
    return servers.filter { server ->
      val matchesRegion = when (region) {
        "All 195" -> true
        "Popular" -> listOf("US", "GB", "IN", "JP", "DE", "CA", "AU", "FR", "BR", "KR", "SG", "IT", "ES", "NL", "CH", "SE", "MX", "AE", "ZA").contains(server.countryCode)
        else -> server.region.equals(region, ignoreCase = true)
      }
      val matchesQuery = query.isBlank() ||
          server.countryName.contains(query, ignoreCase = true) ||
          server.countryCode.contains(query, ignoreCase = true) ||
          server.city.contains(query, ignoreCase = true) ||
          server.unlockedServices.any { it.contains(query, ignoreCase = true) }
      matchesRegion && matchesQuery
    }
  }
